#!/usr/bin/env python3
"""Present saved direct-inverse validation results; no signal calculation."""
from pathlib import Path
import sys,h5py
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[2]
DEFAULT=ROOT/'results/readout/bb0nu_full_ion3mm_20ms_el4mm_mainframe20mm_XeHe15_E300_tau30_seed42/reconstruction/direct_inverse/controls.h5'
def main(path):
 out=path.parent
 with h5py.File(path) as f:
  c=f['cases'];s=f['summary'];x=range(1,int(s['cases'][()])+1)
  fig,axes=plt.subplots(1,2,figsize=(12,4.5),layout='constrained')
  axes[0].plot(x,c['max_bucket_error_ions'][:],'.-',label='Direct · exact voltage')
  axes[0].plot(x,c['max_quantised_error_ions'][:],'.-',label='Direct · 12-bit ADC')
  axes[0].plot(x,c['max_iterative_quantised_error_ions'][:],'.-',label='Iterative · 12-bit ADC')
  axes[0].set_ylabel('Largest bucket error (ions)');axes[0].set_yscale('log')
  axes[0].text(.03,.97,f"Cases = {s['cases'][()]}\nDirect, exact voltage: max = {s['max_bucket_error_ions'][()]:.3g} ions\nDirect, ADC: max = {s['max_quantised_error_ions'][()]:.3g} ions",transform=axes[0].transAxes,va='top',fontsize=9)
  axes[1].plot(x,1000*c['direct_s'][:],'.-',label='Direct inverse')
  axes[1].plot(x,1000*c['iterative_s'][:],'.-',label='Iterative fit')
  axes[1].set_ylabel('Time per nonlinear pad (ms)');axes[1].set_yscale('log')
  axes[1].text(.03,.97,f"Median direct = {1000*s['median_direct_s'][()]:.3g} ms\nMedian iterative = {1000*s['median_iterative_s'][()]:.3g} ms",transform=axes[1].transAxes,va='top',fontsize=9)
  for ax in axes:ax.set_xlabel('Test case');ax.grid(alpha=.2);ax.legend(loc='center right',fontsize=9)
  fig.savefig(out/'comparison.png',dpi=130);plt.close(fig)
  values=[('Cases','cases',''),('Maximum noiseless bucket error','max_bucket_error_ions','ions'),('Maximum noiseless total-charge error','max_total_error_ions','ions'),('Maximum difference from iterative fit','max_difference_from_fit_ions','ions'),('Maximum error with 12-bit ADC','max_quantised_error_ions','ions'),('Iterative fit: maximum error with 12-bit ADC','max_iterative_quantised_error_ions','ions')]
  rows=''.join(f'<tr><td>{label}</td><td>{s[key][()]:.6g} {unit}</td></tr>' for label,key,unit in values)
  prep=''.join(f'<tr><td>{int(c["event_number"][i])}</td><td>{c["base_preparation_s"][i]*1000:.2f}</td><td>{c["direct_preparation_s"][i]*1000:.2f}</td></tr>' for i in range(0,len(c['scale']),5))
  page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><title>ITACA · Direct ion inverse</title><style>body{{font:17px/1.6 system-ui;color:#203343;max-width:1150px;margin:35px auto;padding:0 20px}}h1,h2,a{{color:#185b83}}img{{max-width:100%}}table{{border-collapse:collapse;width:100%}}th,td{{text-align:left;padding:8px;border-bottom:1px solid #ddd}}</style></head><body>
<a href="../../../../../notes/html/index.html">ITACA index</a><h1>Direct ion reconstruction</h1>
<ul><li>Five saved pad-charge shapes, each at five amplitudes.</li><li>Voltages generated by the calibrated nonlinear CSA model.</li><li>Separate checks with exact voltage and with the existing 12-bit ADC.</li><li>No random CSA or ADC noise added. Nonlinear noise-bias checks remain deferred.</li></ul>
<img src="comparison.png" alt="Charge errors and direct versus iterative inversion time">
<table><tr><th>Quantity</th><th>Value</th></tr>{rows}</table>
<h2>Timing</h2><p>Median direct inversion: <strong>{1000*s['median_direct_s'][()]:.3f} ms/pad</strong>. Median iterative fit: <strong>{1000*s['median_iterative_s'][()]:.1f} ms/pad</strong>. Timings exclude preparation; the first iterative case is excluded from its median. No detector simulation, electronics generation or plots are included.</p>
<p>Preparation is shared by all pads with the event's timing. The first row includes first-use compilation.</p>
<table><tr><th>Event shape</th><th>Existing preparation (ms)</th><th>Additional direct-inverse preparation (ms)</th></tr>{prep}</table>
<p><a href="../index.html">Previous 100-event controls: iterative reconstruction</a></p>
</body></html>'''
  (out/'index.html').write_text(page)
 print(out/'index.html')
if __name__=='__main__':main(Path(sys.argv[1]) if len(sys.argv)>1 else DEFAULT)
